  'chat.workStatus.telemetry.responseSpeedDescription': 'Как быстро пришёл итоговый текст. Не включает начальное ожидание, рассуждения и предыдущие вызовы инструментов. Оценка по временным меткам текста, а не измерение скорости провайдером.',
  'chat.workStatus.telemetry.speed': 'Весь ход',
  'chat.workStatus.telemetry.speedDescription': 'Токены, сгенерированные на всех шагах, включая рассуждения, делённые на время без выполнения инструментов. Ожидание модели учитывается, поэтому много коротких вызовов инструментов может снизить это значение.',
  'chat.workStatus.telemetry.elapsed': 'Прошло',
